    [[nodiscard]] constexpr entry const* find(view key) noexcept
    { for(auto const& item : entries) { if(item.key == key) { return &item; } } return nullptr; }
    [[nodiscard]] constexpr view canonical(view key) noexcept
    { if(find(key) != nullptr) { return key; }
      for(auto const& item : aliases) { if(item.name == key) { return item.target; } } return key; }
