    // Normalize HOST documentation words only. c_space covers all C whitespace;
    // retaining one final separator lets Tab request the next catalogue level.
    [[nodiscard]] inline ::fast_io::string completion_spelling(view input, bool trailing = false)
    {
        ::fast_io::string result{}; bool space{};
        for(char c : input)
        {
            if(::fast_io::char_category::c_space::char_is(c)) { space = !result.empty(); continue; }
            if(space) { result.push_back(' '); space = false; }
            result.push_back(c);
        }
        if(space && trailing) { result.push_back(' '); }
        return result;
    }
    template<typename Visitor> inline void visit_completions(view prefix, Visitor visitor)
    {
        auto const spelling{completion_spelling(prefix, true)};
        prefix = spelling.subview(0u);
        if(prefix.size() > maximum_selector_bytes) { return; }
        auto const boundary{prefix.rfind(" ")};
        auto const parent{boundary == ::fast_io::containers::npos ? view{} : prefix.subview(0u, boundary + 1u)};
        auto offer{[&](view key)
        { if(key.starts_with(prefix) && key.starts_with(parent) && key.subview(parent.size()).find(" ") == ::fast_io::containers::npos)
          { visitor(key); } }};
        for(auto const& item : entries) { offer(item.key); }
        if(!prefix.empty())
        { for(auto const& item : aliases) { if(!item.name.empty() && find(item.name) == nullptr) { offer(item.name); } } }
    }
